/* Generated by `pnpm kit:gen` (kit/compile.ts) from kit/fields/strata.ts: edit that file, never this one.
   strataField, the effect's kernel, in GLSL ES 3.00 (the player, the WebGL page) and in WGSL (the WebGPU page),
   and its cost an evaluation. */
export const KERNEL_GLSL = `uniform vec4 uK_shear[1];
uniform vec4 uK_vortex[4];
uniform vec4 uK_bed[2];
uniform vec4 uKF[1];

float kfield(float x, float y) {
  float w = sin(uK_shear[0].z * (uK_shear[0].x * x + uK_shear[0].y * y) + uKF[0].x) * uK_shear[0].w;
  float px = x - uK_shear[0].y * w;
  float py = y + uK_shear[0].x * w;
  for (int i = 0; i < 2; i++) {
    float sn = sin(uKF[0][i + 1]);
    float cx = uK_vortex[7 * i / 4][7 * i % 4] + uK_vortex[(7 * i + 5) / 4][(7 * i + 5) % 4] * cos(uKF[0][i + 1]);
    float cy = uK_vortex[(7 * i + 1) / 4][(7 * i + 1) % 4] + uK_vortex[(7 * i + 6) / 4][(7 * i + 6) % 4] * sn;
    float vx = px - cx;
    float vy = py - cy;
    float t = (uK_vortex[(7 * i + 2) / 4][(7 * i + 2) % 4] + uK_vortex[(7 * i + 3) / 4][(7 * i + 3) % 4] * sn) / (1.0 + (vx * vx + vy * vy) * uK_vortex[(7 * i + 4) / 4][(7 * i + 4) % 4]);
    float t2 = t * t;
    float n = 1.0 / (1.0 + t2);
    float c = (1.0 - t2) * n;
    float s = 2.0 * t * n;
    px = cx + c * vx - s * vy;
    py = cy + s * vx + c * vy;
  }
  float s = uK_bed[0].x * px + uK_bed[0].y * py;
  float r = uK_bed[1].y;
  float b = uK_bed[0].w * s + uK_bed[1].x + uKF[0].w;
  return s + uK_bed[0].z * atan(r * sin(b), 1.0 - r * cos(b));
}`;

export const KERNEL_WGSL = `struct KitKernel {
  shear: array<vec4f, 1>,
  vortex: array<vec4f, 4>,
  bed: array<vec4f, 2>,
  f: array<vec4f, 1>,
}

fn kfield(x: f32, y: f32) -> f32 {
  let w: f32 = sin(kk.shear[0].z * (kk.shear[0].x * x + kk.shear[0].y * y) + kk.f[0].x) * kk.shear[0].w;
  var px: f32 = x - kk.shear[0].y * w;
  var py: f32 = y + kk.shear[0].x * w;
  for (var i: i32 = 0; i < 2; i++) {
    let sn: f32 = sin(kk.f[0][i + 1]);
    let cx: f32 = kk.vortex[7 * i / 4][7 * i % 4] + kk.vortex[(7 * i + 5) / 4][(7 * i + 5) % 4] * cos(kk.f[0][i + 1]);
    let cy: f32 = kk.vortex[(7 * i + 1) / 4][(7 * i + 1) % 4] + kk.vortex[(7 * i + 6) / 4][(7 * i + 6) % 4] * sn;
    let vx: f32 = px - cx;
    let vy: f32 = py - cy;
    let t: f32 = (kk.vortex[(7 * i + 2) / 4][(7 * i + 2) % 4] + kk.vortex[(7 * i + 3) / 4][(7 * i + 3) % 4] * sn) / (1.0 + (vx * vx + vy * vy) * kk.vortex[(7 * i + 4) / 4][(7 * i + 4) % 4]);
    let t2: f32 = t * t;
    let n: f32 = 1.0 / (1.0 + t2);
    let c: f32 = (1.0 - t2) * n;
    let s: f32 = 2.0 * t * n;
    px = cx + c * vx - s * vy;
    py = cy + s * vx + c * vy;
  }
  let s: f32 = kk.bed[0].x * px + kk.bed[0].y * py;
  let r: f32 = kk.bed[1].y;
  let b: f32 = kk.bed[0].w * s + kk.bed[1].x + kk.f[0].w;
  return s + kk.bed[0].z * atan2(r * sin(b), 1.0 - r * cos(b));
}`;

export const KERNEL_COST = 151;
